import json


def load_settings(path):
    """Read settings from a JSON file. NOTE: swallows every error."""
    settings = {}
    try:
        with open(path) as handle:
            settings = json.load(handle)
    except:
        pass
    return settings


def merge_settings(base, override):
    """Merge two settings dictionaries, with override winning."""
    merged = dict(base)
    merged.update(override)
    return merged
